import{_ as i,o as d,c as e,a3 as a}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"孟子","description":"儒家四书之一：性善、仁政、浩然之气，十四篇论辩中的思想张力。","frontmatter":{"title":"孟子","description":"儒家四书之一：性善、仁政、浩然之气，十四篇论辩中的思想张力。","category":"guide","aliases":["孟子","mengzi","孟子译注","孟子篇章","孟子目录"],"source":["《孟子》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/mengzi/index.md","filePath":"lizhimingde/sishu-wujing/mengzi/index.md","lastUpdated":1790316338000}'),r={name:"lizhimingde/sishu-wujing/mengzi/index.md"};function n(l,t,h,s,o,g){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="孟子" tabindex="-1">孟子 <a class="header-anchor" href="#孟子" aria-label="Permalink to &quot;孟子&quot;">​</a></h1><p>《孟子》七篇，各分上下，共十四篇。它是四书里<strong>篇幅最长、论辩最激烈</strong>的一部：孟子不像孔子那样只说一两句，而是整段整段地申辩——与诸侯辩、与时人辩、与弟子辩。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><ul><li><strong>体例</strong>：以长篇对话与论辩为主，兼有短章与格言。篇名取首章开头数字（如「梁惠王」取自孟子见梁惠王），<strong>与内容无主题对应</strong>。</li><li><strong>十四篇</strong>：梁惠王上下、公孙丑上下、滕文公上下、离娄上下、万章上下、告子上下、尽心上下。</li><li><strong>核心命题</strong>： <ul><li><strong>性善</strong>——「人性之善也，犹水之就下也」；四端（恻隐、羞恶、辞让、是非）</li><li><strong>仁政</strong>——「民为贵，社稷次之，君为轻」；制民之产、五亩之宅</li><li><strong>浩然之气</strong>——「我善养吾浩然之气」「富贵不能淫，贫贱不能移，威武不能屈」</li><li><strong>义利之辨</strong>——「何必曰利？亦有仁义而已矣」</li></ul></li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它是儒家思想里最有锋芒的一支</strong>：敢说「闻诛一夫纣矣，未闻弑君也」，敢把「民」放在「君」前。</li><li><strong>它给「修养」找了一个内在根据</strong>：性善不只是主张，而是一整套「存心养性」的工夫论。</li><li><strong>它是后世士人风骨的来源</strong>：从「大丈夫」到「舍我其谁」，两千年的士人骨气多从这里取。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>先读《梁惠王》上下</strong>——孟子与诸侯的对答最见其锋芒，也为全书的仁政主张定了调；</li><li><strong>再读《公孙丑》上下</strong>——「浩然之气」「不动心」「知言」等核心工夫都在这里；</li><li><strong>《告子》上下</strong>是性善论的主战场，与告子的往复辩论值得细看；</li><li><strong>《尽心》上下</strong>多格言与总论，适合放在最后读；</li><li><strong>注本</strong>：可参考杨伯峻《孟子译注》、朱熹《四书章句集注》。</li></ol><h2 id="篇目" tabindex="-1">篇目 <a class="header-anchor" href="#篇目" aria-label="Permalink to &quot;篇目&quot;">​</a></h2><p>《孟子》七篇，各分上下，共十四篇。篇名取自首章开头数字，<strong>与内容无主题对应</strong>。</p><p>当前先把十四篇的篇名与路径立住，原文与逐篇解读按顺序分批推进。</p><h3 id="七篇-各分上下" tabindex="-1">七篇（各分上下） <a class="header-anchor" href="#七篇-各分上下" aria-label="Permalink to &quot;七篇（各分上下）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">序</th><th>篇</th><th>首章起句</th><th>入口</th></tr></thead><tbody><tr><td style="text-align:right;">01</td><td>梁惠王上</td><td>孟子见梁惠王</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-01">孟子·梁惠王上</a></td></tr><tr><td style="text-align:right;">02</td><td>梁惠王下</td><td>庄暴见孟子</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-02">孟子·梁惠王下</a></td></tr><tr><td style="text-align:right;">03</td><td>公孙丑上</td><td>公孙丑问曰：夫子当路于齐</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-03">孟子·公孙丑上</a></td></tr><tr><td style="text-align:right;">04</td><td>公孙丑下</td><td>孟子曰：天时不如地利</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-04">孟子·公孙丑下</a></td></tr><tr><td style="text-align:right;">05</td><td>滕文公上</td><td>滕文公为世子</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-05">孟子·滕文公上</a></td></tr><tr><td style="text-align:right;">06</td><td>滕文公下</td><td>陈代曰：不见诸侯</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-06">孟子·滕文公下</a></td></tr><tr><td style="text-align:right;">07</td><td>离娄上</td><td>孟子曰：离娄之明</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-07">孟子·离娄上</a></td></tr><tr><td style="text-align:right;">08</td><td>离娄下</td><td>孟子曰：舜生于诸冯</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-08">孟子·离娄下</a></td></tr><tr><td style="text-align:right;">09</td><td>万章上</td><td>万章问曰：舜往于田</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-09">孟子·万章上</a></td></tr><tr><td style="text-align:right;">10</td><td>万章下</td><td>孟子曰：伯夷目不视恶色</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-10">孟子·万章下</a></td></tr><tr><td style="text-align:right;">11</td><td>告子上</td><td>告子曰：性犹杞柳也</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-11">孟子·告子上</a></td></tr><tr><td style="text-align:right;">12</td><td>告子下</td><td>任人有问屋庐子曰</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-12">孟子·告子下</a></td></tr><tr><td style="text-align:right;">13</td><td>尽心上</td><td>孟子曰：尽其心者</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-13">孟子·尽心上</a></td></tr><tr><td style="text-align:right;">14</td><td>尽心下</td><td>孟子曰：不仁哉梁惠王也</td><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-14">孟子·尽心下</a></td></tr></tbody></table><h3 id="内容侧重-读法参考" tabindex="-1">内容侧重（读法参考） <a class="header-anchor" href="#内容侧重-读法参考" aria-label="Permalink to &quot;内容侧重（读法参考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>篇</th><th>侧重</th></tr></thead><tbody><tr><td>梁惠王上下</td><td>仁政、王道与霸道的对辩；与齐宣王、梁惠王的往复</td></tr><tr><td>公孙丑上下</td><td>不动心、浩然之气、知言；义利与王道之辨</td></tr><tr><td>滕文公上下</td><td>井田、丧礼、农商；对墨者、农家的辩驳</td></tr><tr><td>离娄上下</td><td>仁、义、礼、智的短论与格言；「民为贵」在此</td></tr><tr><td>万章上下</td><td>论舜、尧、禹、汤、孔子等；尚友与出处</td></tr><tr><td>告子上下</td><td>性善论的主战场；「富贵不能淫」在此</td></tr><tr><td>尽心上下</td><td>存心养性、尽性知天；全书的总收束</td></tr></tbody></table><p>（篇名与内容并无主题对应，此表只是读法参考。）</p><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li><strong>十四篇已全部落成</strong>：梁惠王上下、公孙丑上下、滕文公上下、离娄上下、万章上下、告子上下、尽心上下——原文（每节一节，竹简／经典两种阅读）、<strong>逐段白话释义</strong>（经典阅读模式下点各段标题旁的 ▸ 展开）、注音字词卡、三问解读、现代重述与关联俱备。</li><li><strong>段级释义的体例</strong>：每篇节内再分段（<code>sections</code>），每段有 <code>label</code>（触发条）与 <code>note</code>（本节白话串讲，50–330 字）。</li><li><strong>分节依据</strong>：采用通行本（赵岐章句／朱熹集注）的分节，全篇合计 260 节；页内每一节对应 <code>&lt;DaoTextReading&gt;</code> 的一个 <code>sections</code> 对象。各篇节数：梁惠王上 7 / 下 16、公孙丑上 9 / 下 14、滕文公上 5 / 下 10、离娄上 28 / 下 33、万章上 9 / 下 9、告子上 20 / 下 16、尽心上 46 / 下 38。</li><li><strong>原文保留原字</strong>（如「由水之就下」的由、「涂有饿莩」的涂、「放辟邪侈」的辟），通假与异文在释义中说明。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',20)])])}const m=i(r,[["render",n]]);export{c as __pageData,m as default};
